module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [1:0] counter;
reg [9:0] accum_register;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        accum_register <= 10'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        valid_out <= 1'b0; // Default valid_out is low

        if (valid_in) begin
            accum_register <= accum_register + data_in;
            counter <= counter + 1'b1;

            if (counter == 2'b11) begin // When counter reaches 3
                data_out <= accum_register;
                valid_out <= 1'b1; // Assert valid_out for one cycle
                counter <= 2'b00; // Reset counter for the next batch
                accum_register <= 10'b0; // Reset accumulator
            end
        end
    end
end

endmodule

