module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] carry; 

    assign carry[0] = cin;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : full_adder
            wire a_bit, b_bit, c_in, s, c_out;

            assign a_bit = a[i];
            assign b_bit = b[i];
            assign c_in = carry[i];

            assign sum[i] = a_bit ^ b_bit ^ c_in;
            assign carry[i + 1] = (a_bit & b_bit) | (c_in & (a_bit ^ b_bit));
        end
    endgenerate

    assign cout = carry[8];

endmodule

