module adder_32bit(A,B,S,C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire [16:1] S1, S2;
    wire C16;
    wire [16:1] P1, G1, P2, G2;

    // First 16-bit CLA block
    assign P1 = A[16:1] ^ B[16:1];
    assign G1 = A[16:1] & B[16:1];

    assign C16 = G1[16] | (P1[16] & 1'b0);

    assign S1 = P1 ^ {C16, C16, C16, C16, C16, C16, C16, C16, C16, C16, C16, C16, C16, C16, C16, C16};

    // Second 16-bit CLA block
    assign P2 = A[32:17] ^ B[32:17];
    assign G2 = A[32:17] & B[32:17];

    assign C32 = G2[16] | (P2[16] & C16);

    assign S2 = P2 ^ {C32, C32, C32, C32, C32, C32, C32, C32, C32, C32, C32, C32, C32, C32, C32, C32};

    // Final sum output
    assign S = {S2, S1};

