    if (!rst_n) begin
        adda_reg2 <= 0;
        addb_reg2 <= 0;
        i_en_reg2 <= 0;
        sum_stage2 <= 0;
    end else begin
        adda_reg2 <= adda_reg1;
        addb_reg2 <= addb_reg1;
        i_en_reg2 <= i_en_reg1;
        sum_stage2 <= sum_stage1;
