module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [2:0] state, next_state;

// State encoding
localparam S0 = 3'b000, // Initial state
           S1 = 3'b001, // '1' detected
           S2 = 3'b010, // '10' detected
           S3 = 3'b011, // '100' detected
           S4 = 3'b100, // '1001' detected
           S5 = 3'b101; // '10011' detected

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
        MATCH <= 0;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        S0: if (IN) next_state = S1; else next_state = S0;
        S1: if (!IN) next_state = S2; else next_state = S1;
        S2: if (IN) next_state = S3; else next_state = S0;
        S3: if (IN) next_state = S4; else next_state = S0;
        S4: if (!IN) next_state = S5; else next_state = S1;
        S5: begin
            MATCH = 1;
            next_state = IN ? S4 : S0; // Loop back after detection
        end
        default: next_state = S0;
    endcase
end

endmodule

