                  2'b10: p <= p - multiplicand; // Subtract multiplicand
                  default: ; // Do nothing
               endcase
               multiplier <= {1'b0, multiplier[15:1]}; // Shift right
               multiplicand <= multiplicand << 1; // Shift left
