`timescale 1ns / 1ps
module multi_booth_8bit (p, rdy, clk, reset, a, b);
   input clk, reset;
   input [7:0] a, b;
   output reg [15:0] p;
   output reg rdy;

   reg [15:0] multiplier;
   reg [15:0] multiplicand;
   reg [4:0] ctr;
   reg [1:0] current_state, next_state;

   parameter IDLE = 2'b00, PROCESS = 2'b01, DONE = 2'b10;

   always @(posedge clk or posedge reset) begin
       if (reset) begin
           multiplier <= {8'b0, a}; // Sign extend a
           multiplicand <= {8'b0, b}; // Sign extend b
           p <= 16'b0;
           ctr <= 5'b0;
           rdy <= 1'b0;
           current_state <= IDLE;
       end else begin
           current_state <= next_state;
       end
   end

   always @(*) begin
       next_state = current_state;
       case (current_state)
           IDLE: begin
               if (multiplier[1:0] != 2'b00) begin
                   next_state = PROCESS;
               end
           end
           PROCESS: begin
               if (ctr == 5'd16) begin
                   next_state = DONE;
               end
           end
           DONE: begin
               rdy = 1'b1;
           end
       endcase
   end

   always @(posedge clk) begin
       if (current_state == PROCESS) begin
           case (multiplier[1:0])
               2'b01: p <= p + multiplicand; // Add
               2'b10: p <= p - multiplicand; // Subtract
               default: ;
           endcase
           multiplier <= {1'b0, multiplier[15:1]}; // Shift
           ctr <= ctr + 1'b1; // Increment counter
       end
   end
endmodule

