module multi_pipe_4bit#(
	parameter size = 4
)(
	input 						clk 		,   
	input 						rst_n		,
	input	[size-1:0]			mul_a		,
	input	[size-1:0]			mul_b		,

 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [size-1:0] partial_product [0:size-1];
reg [N-1:0] sum_stage1, sum_stage2;

integer i;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		mul_out <= 0;
		sum_stage1 <= 0;
		sum_stage2 <= 0;
		for (i = 0; i < size; i = i + 1) begin
			partial_product[i] <= 0;
		end
	end else begin
		// Generate partial products
		for (i = 0; i < size; i = i + 1) begin
			if (mul_b[i]) begin
				partial_product[i] <= mul_a << i;
			end else begin
				partial_product[i] <= 0;
			end
		end

		// Accumulate partial products in stage 1
		sum_stage1 <= partial_product[0];
		for (i = 1; i < size; i = i + 1) begin
			sum_stage1 <= sum_stage1 + partial_product[i];
		end

		// Store the accumulated result in stage 2
		sum_stage2 <= sum_stage1;
		mul_out <= sum_stage2;
	end
end

