 	output	reg	[size*2-1:0]	mul_out		
);

parameter N = 2 * size;

reg [N-1:0] partial_sum_stage1;
reg [N-1:0] partial_sum_stage2;
reg [size-1:0] mul_a_shifted;
reg [size-1:0] mul_b_shifted;
integer i;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		partial_sum_stage1 <= 0;
		partial_sum_stage2 <= 0;
		mul_out <= 0;
	end else begin
		mul_a_shifted = mul_a;
		partial_sum_stage1 = 0;

		for (i = 0; i < size; i = i + 1) begin
			if (mul_b[i]) begin
				partial_sum_stage1 = partial_sum_stage1 + (mul_a_shifted << i);
			end
		end

		partial_sum_stage2 <= partial_sum_stage1;
		mul_out <= partial_sum_stage2;
	end
end

endmodule

