module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [3:0] data;
reg [1:0] cnt;
reg valid_out_reg;
assign dout = data[3];
assign valid_out = valid_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data <= 4'b0000;
        cnt <= 2'b00;
        valid_out_reg <= 1'b0;
    end else begin
        if (cnt < 2'b11) begin
            valid_out_reg <= 1'b1;
            data <= {data[2:0], 1'b0}; // Shift left
            cnt <= cnt + 1;
        end else begin
            valid_out_reg <= 1'b0;
            data <= d; // Load new data on completion
            cnt <= 2'b00;
        end
    end
end

endmodule

