reg dout_reg;
reg valid_reg;

assign dout = dout_reg;
assign valid_out = valid_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 2'b00;
        data <= 4'b0000;
        dout_reg <= 1'b0;
        valid_reg <= 1'b0;
    end else begin
        if (cnt == 2'b00) begin
            data <= d; // Load new data on the first cycle
            valid_reg <= 1'b1; // Assert valid output
        end else if (cnt < 2'b11) begin
            valid_reg <= 1'b1; // Assert valid output for subsequent bits
        end else begin
            valid_reg <= 1'b0; // Deassert valid after last bit
        end

        dout_reg <= data[3]; // Output the MSB
        data <= {data[2:0], 1'b0}; // Shift data left

        if (cnt == 2'b11) begin
            cnt <= 2'b00; // Reset counter after 4 cycles
        end else begin
            cnt <= cnt + 1; // Increment counter
        end
    end
end

endmodule

