module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    reg prev_data;

    localparam IDLE = 2'b00;
    localparam RISING = 2'b01;
    localparam FALLING = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
            prev_data <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in == 1 && prev_data == 0) begin
                        state <= RISING;
                    end
                    data_out <= 0;
                end
                RISING: begin
                    if (data_in == 0 && prev_data == 1) begin
                        state <= FALLING;
                    end
                end
                FALLING: begin
                    if (data_in == 0 && prev_data == 0) begin
                        data_out <= 1; // Pulse detected
                        state <= IDLE;
                    end
                end
            endcase
            prev_data <= data_in;
        end
    end

endmodule

module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    parameter IDLE = 2'b00, RISING = 2'b01, FALLING = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= RISING;
                    end
                end
                RISING: begin
                    if (!data_in) begin
                        state <= FALLING;
                    end
                end
                FALLING: begin
                    data_out <= 1;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule

module pulse_detect(    
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state; // State register
    reg prev_data;   // Previous data_in value

    // State encoding
    localparam IDLE = 2'b00;
    localparam DETECTING = 2'b01;
    localparam PULSE_END = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 0;
            prev_data <= 0;
        end else begin
            case (state)
                IDLE: begin
                    data_out <= 0;
                    if (data_in == 1 && prev_data == 0) begin
                        state <= DETECTING;
                    end
                end

                DETECTING: begin
                    if (data_in == 0 && prev_data == 1) begin
                        state <= PULSE_END;
                    end
                end

                PULSE_END: begin
                    data_out <= 1;
                    state <= IDLE; // Go back to IDLE after pulse
                end
            endcase

            prev_data <= data_in; // Update previous data
        end
    end

endmodule

