module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
    );

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    wire signed [31:0] signed_a = a;
    wire signed [31:0] signed_b = b;

    assign zero = (res == 32'b0);
    assign negative = res[31];

    always @(*) begin
        carry = 1'b0;
        overflow = 1'b0;
        flag = 1'b0;
        case (aluc)
            ADD: begin
                {carry, res} = a + b;
                overflow = (signed_a[31] == signed_b[31]) && (res[31] != signed_a[31]);
            end
            ADDU: begin
                {carry, res} = a + b;
            end
            SUB: begin
                {carry, res} = a - b;
                overflow = (signed_a[31] != signed_b[31]) && (res[31] != signed_a[31]);
            end
            SUBU: begin
                {carry, res} = a - b;
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = (signed_a < signed_b) ? 32'b1 : 32'b0;
            SLTU: res = (a < b) ? 32'b1 : 32'b0;
            SLL: res = b << a[4:0];
            SRL: res = b >> a[4:0];
            SRA: res = $signed(b) >>> a[4:0];
            SLLV: res = b << a[4:0];
            SRLV: res = b >> a[4:0];
            SRAV: res = $signed(b) >>> a[4:0];
            LUI: res = {b[15:0], 16'b0};
            default: res = 32'bz; // High impedance for invalid opcodes
        endcase
        r = res;
    end
endmodule

module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
    );

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg signed [31:0] signed_a, signed_b;
    reg overflow_flag, carry_flag, zero_flag, negative_flag, flag_signal;

    always @(*) begin
        signed_a = a;
        signed_b = b;
        overflow_flag = 1'b0;
        carry_flag = 1'b0;
        flag_signal = 1'b0;

        case (aluc)
            ADD: begin
                r = signed_a + signed_b;
                carry_flag = (r < signed_a) || (r < signed_b);
                overflow_flag = (signed_a > 0 && signed_b > 0 && r < 0) || (signed_a < 0 && signed_b < 0 && r > 0);
            end
            ADDU: begin
                r = a + b;
                carry_flag = (r < a) || (r < b);
            end
            SUB: begin
                r = signed_a - signed_b;
                carry_flag = (r > signed_a);
                overflow_flag = (signed_a < 0 && signed_b > 0 && r > 0) || (signed_a > 0 && signed_b < 0 && r < 0);
            end
            SUBU: begin
                r = a - b;
                carry_flag = (r > a);
            end
            AND: r = a & b;
            OR: r = a | b;
            XOR: r = a ^ b;
            NOR: r = ~(a | b);
            SLT: r = (signed_a < signed_b) ? 32'b1 : 32'b0;
            SLTU: r = (a < b) ? 32'b1 : 32'b0;
            SLL: r = b << a[4:0];
            SRL: r = b >> a[4:0];
            SRA: r = signed_b >>> a[4:0];
            SLLV: r = b << a[4:0];
            SRLV: r = b >> a[4:0];
            SRAV: r = signed_b >>> a[4:0];
            LUI: r = {b[15:0], 16'b0};
            default: r = 32'bz; // High impedance for invalid opcodes
        endcase
    end

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = carry_flag;
    assign overflow = overflow_flag;
    assign flag = flag_signal;

endmodule

