				cnt <= cnt + 1;
			else 
				cnt <= 0;
		end
	end

	always @(*) begin
		case(state)
			idle: next_state = s1_red;
			s1_red: begin
				if (cnt >= red_time) 
					next_state = s2_yellow; 
				else 
					next_state = s1_red;
			end
			s2_yellow: begin
				if (cnt >= yellow_time) 
					next_state = s3_green; 
				else 
					next_state = s2_yellow;
			end
			s3_green: begin
				if (cnt >= green_time) 
					next_state = s1_red; 
				else 
					next_state = s3_green;
			end
			default: next_state = idle;
		endcase
	end

	always @(posedge clk or negedge rst_n) begin
		if(!rst_n) begin
			red <= 1;
			yellow <= 0;
			green <= 0;
			green_time <= 8'd100; // Default green time
			yellow_time <= 8'd30; // Default yellow time
			red_time <= 8'd150;   // Default red time
		end else begin
			case(state)
				s1_red: begin
					red <= 1;
					yellow <= 0;
					green <= 0;
				end
				s2_yellow: begin
					red <= 0;
					yellow <= 1;
					green <= 0;
				end
				s3_green: begin
					red <= 0;
					yellow <= 0;
					green <= 1;
					if (pass_request) 
						green_time <= green_time + 8'd20; // Adjust green time on request
				end
				default: begin
					red <= 0;
					yellow <= 0;
					green <= 0;
				end
			endcase
		end
	end

endmodule

